package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateEmailException;

/**
 * Runs after {@link ValidateNewOwner} (which has lower-cased the email) and before
 * {@link BuildOwner}. Rejects the create with a 409 when any existing owner shares the same
 * lower-cased email, so no two owners can share an email address. An absent email is never a
 * conflict. Publishes nothing; it is a validation gate that only escalates on conflict.
 */
public class ValidateUniqueEmail {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateEmailException {
        String email = request.getEmail();
        if (email == null) {
            return;
        }
        for (Owner existing : ownerRepository.findAll()) {
            if (email.equals(OwnerEmail.normalize(existing.getEmail()))) {
                throw new DuplicateEmailException(
                        "Email " + email + " is already used by another owner");
            }
        }
    }
}
===== ValidateUniqueHousehold =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.List;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;

/**
 * Runs after {@link ValidateUniqueTelephone} and before {@link BuildOwner}. A read-only
 * validation gate: it detects whether the new owner would join an existing household (see
 * {@link Household}) and decides allow or reject, writing nothing to the database.
 *
 * <p>When another owner already shares the household and the request did not opt in with
 * {@code sharesHousehold = true}, rejects the create with a 409. Otherwise it publishes the
 * {@link Household.Id} for the rest of the pipeline — the shared identifier when joining a
 * household, {@link Household.Id#ABSENT} when not — leaving {@link ApplySharedHousehold} to
 * back-fill existing members and {@link BuildOwner} to stamp the new owner.
 */
public class ValidateUniqueHousehold {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository,
            Out<Household.Id> householdIdOut) throws DuplicateHouseholdException {
        List<Owner> members = Household.membersOf(request, ownerRepository);
        if (members.isEmpty()) {
            // Not joining any household: nothing to share, nothing to reject.
            householdIdOut.set(Household.Id.ABSENT);
            return;
        }
        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
            throw new DuplicateHouseholdException("An owner named " + request.getLastName()
                    + " already exists at " + request.getAddress());
        }
        householdIdOut.set(Household.idFor(request));
    }
}
===== OwnerTelephone =====
package org.springframework.samples.petclinic.rest.function.owner;

/**
 * Single source of truth for the owner telephone normalization rule, shared by the
 * owner-create pipeline. The uniqueness check only holds if both the value stored for a
 * new owner and the values compared against existing owners are normalized identically,
 * so that rule lives here rather than being duplicated across steps.
 */
final class OwnerTelephone {

    private OwnerTelephone() {
    }

    /**
     * Normalize a telephone to E.164 form, or {@code null} if the input is {@code null} or
     * cannot form a valid E.164 number.
     *
     * <p>Spaces, dashes and brackets are stripped. A leading {@code '+'} and country code are
     * kept when present; otherwise the country code {@code '+61'} is assumed and a single
     * leading {@code '0'} is dropped from the national digits. The result is valid only when
     * it has 8 to 15 digits after the {@code '+'}; anything else (including stray non-digit
     * characters) yields {@code null}. In addition, for a recognised country code the
     * national number (the digits after the country code) must have the exact length that
     * country requires — {@code '+61'} requires 9 national digits and {@code '+1'} requires
     * 10 — otherwise the result is {@code null}. The function is idempotent: an already-E.164
     * value normalizes to itself.
     */
    static String normalize(String telephone) {
        if (telephone == null) {
            return null;
        }
        String cleaned = telephone.replaceAll("[\\s()-]", "");
        boolean hasPlus = cleaned.startsWith("+");
        String digits = hasPlus ? cleaned.substring(1) : cleaned;
        if (!digits.matches("[0-9]+")) {
            return null;
        }
        String e164Digits;
        if (hasPlus) {
            e164Digits = digits;
        }
        else {
            String national = digits.startsWith("0") ? digits.substring(1) : digits;
            e164Digits = "61" + national;
        }
        if (e164Digits.length() < 8 || e164Digits.length() > 15) {
            return null;
        }
        if (!hasValidNationalLength(e164Digits)) {
            return null;
        }
        return "+" + e164Digits;
    }

    /**
     * For a recognised country code, require the exact national-number length that country
     * uses. {@code '+61'} expects 9 national digits and {@code '+1'} expects 10. Unrecognised
     * country codes are left to the generic 8-to-15 digit length check.
     */
    private static boolean hasValidNationalLength(String e164Digits) {
        if (e164Digits.startsWith("61")) {
            return e164Digits.length() - 2 == 9;
        }
        if (e164Digits.startsWith("1")) {
            return e164Digits.length() - 1 == 10;
        }
        return true;
    }
}
===== OwnerEmail =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.regex.Pattern;

/**
 * Single source of truth for the owner email rule, shared by the owner pipelines. An
 * owner may omit the email, but when supplied it must be a syntactically valid address
 * and is stored and returned lower-cased. Keeping the validity check and the
 * lower-casing here keeps the create and update paths consistent.
 */
final class OwnerEmail {

    /**
     * Pragmatic syntactic check for a single address: a non-empty local part, an
     * {@code @}, then a domain with at least one dot and no whitespace. Rejects values
     * like {@code not-an-email} that lack an {@code @} and a dotted domain.
     */
    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s.]+(\\.[^@\\s.]+)+$");

    private OwnerEmail() {
    }

    /** Whether {@code email} is a syntactically valid address. */
    static boolean isValid(String email) {
        return email != null && EMAIL.matcher(email).matches();
    }

    /** Lower-case and trim the email, or {@code null} when absent/blank. */
    static String normalize(String email) {
        if (email == null) {
            return null;
        }
        String trimmed = email.trim();
        return trimmed.isEmpty() ? null : trimmed.toLowerCase();
    }
}
===== OwnerAddress =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;
import java.util.Map;

/**
 * Canonical address normalization for the owner-create pipeline. Applied once when an owner is
 * created so the stored and returned {@code address} is canonical, and reused for every address
 * comparison (household duplicate detection in {@link Household} and the shared household id) so
 * all steps compare the same form.
 *
 * <p>Normalization: trim, collapse any run of whitespace to a single space, upper-case, and
 * expand common abbreviations as whole words — {@code ST -> STREET}, {@code RD -> ROAD},
 * {@code AVE -> AVENUE}. Yields {@code ""} for a {@code null} or whitespace-only input.
 */
final class OwnerAddress {

    private static final Map<String, String> ABBREVIATIONS = Map.of(
            "ST", "STREET",
            "RD", "ROAD",
            "AVE", "AVENUE");

    private OwnerAddress() {
    }

    static String normalize(String value) {
        if (value == null) {
            return "";
        }
        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
        if (collapsed.isEmpty()) {
            return "";
        }
        String[] tokens = collapsed.split(" ");
        StringBuilder sb = new StringBuilder(collapsed.length());
        for (int i = 0; i < tokens.length; i++) {
            if (i > 0) {
                sb.append(' ');
            }
            sb.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
        }
        return sb.toString();
    }
}
===== Household =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Shared household rules for the owner-create pipeline. A household is the set of owners with
 * the same last name at the same address, compared case-insensitively with collapsed
 * whitespace. The membership match and the stable identifier are defined once here so the gate
 * ({@link ValidateUniqueHousehold}), the back-fill ({@link ApplySharedHousehold}) and the new
 * owner ({@link BuildOwner}) all agree on them.
 */
final class Household {

    private Household() {
    }

    /**
     * The household identifier published between steps. A dedicated type keeps the variable
     * unambiguous (OfficeFloor matches variables by type) and distinct from other strings in
     * the pipeline. {@link #ABSENT} (an empty value) means the new owner is not joining a
     * shared household.
     */
    record Id(String value) {

        static final Id ABSENT = new Id("");

        boolean isPresent() {
            return this.value != null && !this.value.isBlank();
        }
    }

    /**
     * Existing owners that share the request's household (same normalized last name and
     * address).
     */
    static List<Owner> membersOf(OwnerFieldsDto request, OwnerRepository ownerRepository) {
        String lastName = normalize(request.getLastName());
        String address = OwnerAddress.normalize(request.getAddress());
        List<Owner> members = new ArrayList<>();
        for (Owner existing : ownerRepository.findAll()) {
            if (lastName.equals(normalize(existing.getLastName()))
                    && address.equals(OwnerAddress.normalize(existing.getAddress()))) {
                members.add(existing);
            }
        }
        return members;
    }

    /**
     * Stable identifier for the request's household: the first 12 upper-case hex characters of
     * the SHA-256 of the normalized last name and address, so every owner in the same household
     * derives the same value regardless of creation order.
     */
    static Id idFor(OwnerFieldsDto request) {
        String seed = normalize(request.getLastName()) + "\n" + OwnerAddress.normalize(request.getAddress());
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                    .digest(seed.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < 6; i++) {
                sb.append(String.format("%02X", digest[i]));
            }
            return new Id(sb.toString());
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("SHA-256 not available", ex);
        }
    }

    /**
     * Normalize a name or address for household comparison: trim, collapse any run of
     * whitespace to a single space, and lower-case. Yields {@code ""} for a {@code null} input.
     */
    private static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }
}
===== BuildOwner =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.repository.OwnerRepository;

public class BuildOwner {

    public void service(@Val OwnerFieldsDto request, @Val Household.Id householdId,
            OwnerMapper ownerMapper, OwnerRepository ownerRepository, Out<Owner> built) {
        Owner owner = ownerMapper.toOwner(request);
        // The effective registration date defaults an unsupplied value to the server's
        // current date, then rolls any weekend forward to the next Monday so derived values
        // (e.g. the membership number's year) use the adjusted business day.
        owner.setRegistrationDate(BusinessDay.effectiveRegistrationDate(owner.getRegistrationDate()));
        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName(), ownerRepository));
        // Record how many existing owners already share this first+last name (case-insensitive),
        // counted before this owner is persisted so the value is fixed at creation time.
        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName(), ownerRepository));
        // Join a shared household when the gate resolved an identifier.
        if (householdId != null && householdId.isPresent()) {
            owner.setHouseholdId(householdId.value());
        }
        built.set(owner);
    }

    /**
     * Build the '<CITY3>-<LAST3>-<NNNN>' customer code: CITY3 is the upper-cased first three
     * letters of the city, LAST3 the upper-cased first three letters of the last name, and NNNN
     * a per-city 4-digit zero-padded sequence equal to one more than the number of owners
     * already in that city (e.g. 'LON-SMI-0007').
     */
    private static String nextCustomerCode(String city, String lastName, OwnerRepository ownerRepository) {
        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
        int sequence = countOwnersInCity(city, ownerRepository) + 1;
        return String.format("%s-%s-%04d", city3, last3, sequence);
    }

    /**
     * Count the existing owners in the given city, compared case-insensitively.
     */
    private static int countOwnersInCity(String city, OwnerRepository ownerRepository) {
        int count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (city.equalsIgnoreCase(existing.getCity())) {
                count++;
            }
        }
        return count;
    }

    /**
     * Count the existing owners whose first and last names both match the given names,
     * compared case-insensitively.
     */
    private static int countNamesakes(String firstName, String lastName,
            OwnerRepository ownerRepository) {
        int count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (firstName.equalsIgnoreCase(existing.getFirstName())
                    && lastName.equalsIgnoreCase(existing.getLastName())) {
                count++;
            }
        }
        return count;
    }
}
===== ValidateNewOwner =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.ArrayList;
import java.util.List;

import net.officefloor.plugin.variable.Out;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * First step of {@code POST /api/owners}. Rejects a body that is missing or blank in any
 * required field (firstName, lastName, address, city, telephone) with a 400 listing the
 * offending field names, normalizes the telephone to E.164 form (400 if it cannot form a
 * valid E.164 number), then publishes the body for {@link BuildOwner}.
 *
 * <p>Runs before {@link BuildOwner} and binds {@code @RequestBody} without {@code @Valid}
 * so the required-field check produces the {@code errors} response shape rather than the
 * generic schema-validation shape, and so an invalid body is a 400 here.
 */
public class ValidateNewOwner {

    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
            throws MissingOwnerFieldsException, InvalidTelephoneException, InvalidEmailException {
        // Normalize the address up front so the required-field check sees the canonical form
        // (an address blank after normalization is rejected) and every later step — storage,
        // the response and household comparisons — carries the same normalized value.
        request.setAddress(OwnerAddress.normalize(request.getAddress()));
        List<String> missing = new ArrayList<>();
        if (isBlank(request.getFirstName())) {
            missing.add("firstName");
        }
        if (isBlank(request.getLastName())) {
            missing.add("lastName");
        }
        if (isBlank(request.getAddress())) {
            missing.add("address");
        }
        if (isBlank(request.getCity())) {
            missing.add("city");
        }
        if (isBlank(request.getTelephone())) {
            missing.add("telephone");
        }
        if (!missing.isEmpty()) {
            throw new MissingOwnerFieldsException(missing);
        }
        String e164 = OwnerTelephone.normalize(request.getTelephone());
        if (e164 == null) {
            throw new InvalidTelephoneException(
                    "Telephone is not a valid E.164 number: " + request.getTelephone());
        }
        request.setTelephone(e164);
        String email = OwnerEmail.normalize(request.getEmail());
        if (email != null && !OwnerEmail.isValid(email)) {
            throw new InvalidEmailException("Email is not a valid address: " + request.getEmail());
        }
        request.setEmail(email);
        validated.set(request);
    }

    private static boolean isBlank(String value) {
        return value == null || value.isBlank();
    }
}

